{"code":"import random

def generate(rng):
    # A partitioned canvas: 3x3 or 4x4 rectangular rooms separated by color-7 walls.
    n = rng.choice([3, 4])
    room = rng.choice([3, 4, 5])
    h = n*room + n-1
    w = n*room + n-1
    g = [[0 for _ in range(w)] for _ in range(h)]
    walls = 7
    for r in range(h):
        if r % (room+1) == room:
            for c in range(w): g[r][c] = walls
    for c in range(w):
        if c % (room+1) == room:
            for r in range(h): g[r][c] = walls
    # place several small color-9 motifs, generally near room centers/edges,
    # leaving many empty rooms as in the demonstrated task
    colors = [9, 8, 6]
    for br in range(n):
        for bc in range(n):
            if rng.random() < rng.uniform(.25, .65):
                y0, x0 = br*(room+1), bc*(room+1)
                col = rng.choice(colors)
                kind = rng.randrange(4)
                cy, cx = rng.randrange(1, room-1), rng.randrange(1, room-1)
                pts = [(cy,cx)]
                if kind == 1: pts += [(cy,cx+1),(cy,cx-1)]
                elif kind == 2: pts += [(cy+1,cx),(cy-1,cx)]
                else: pts += [(cy,cx+1),(cy+1,cx)]
                for dy,dx in pts:
                    if 0 <= cy+dy-cy < room and 0 <= cx+dx-cx < room:
                        yy,xx=y0+dy,x0+dx
                        if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == 0: g[yy][xx]=col
    return g"}

